### Python

```python
import sys


# 每一段用 [bit, len] 表示
# bit 表示这一段是 0 还是 1
# len 表示这一段长度

# 向末尾加入一段，若和栈顶相同则合并
def add_seg(st, bit, length):
    if length <= 0:
        return
    if st and st[-1][0] == bit:
        st[-1][1] += length
    else:
        st.append([bit, length])


# 删除末尾一位
def remove_last_bit(st):
    if not st:
        return
    st[-1][1] -= 1
    if st[-1][1] == 0:
        st.pop()


# 处理操作串
def solve_ops(s):
    st = []      # 二进制连续段
    cnt = 0      # 当前二进制中 1 的个数
    ans = []

    for ch in s:
        if ch == '+':
            if not st:
                # 0 + 1 = 1
                add_seg(st, 1, 1)
                cnt += 1
            elif st[-1][0] == 0:
                # 最低位是 0，直接改成 1
                remove_last_bit(st)
                add_seg(st, 1, 1)
                cnt += 1
            else:
                # 末尾若干个 1 进位
                k = st[-1][1]
                st.pop()
                cnt -= k

                if not st:
                    # 原来全是 1，例如 111 + 1 = 1000
                    add_seg(st, 1, 1)
                    cnt += 1
                    add_seg(st, 0, k)
                else:
                    # 前面一定是 0，把那个 0 变成 1，再补 k 个 0
                    remove_last_bit(st)
                    add_seg(st, 1, 1)
                    cnt += 1
                    add_seg(st, 0, k)

        elif ch == '-':
            if not st:
                # 0 不能再减
                pass
            elif st[-1][0] == 1:
                # 最低位是 1，直接减掉这一位
                remove_last_bit(st)
                cnt -= 1

                # 若结果还大于 0，则最低位补成 0
                if st:
                    add_seg(st, 0, 1)
            else:
                # 末尾若干个 0，需要借位
                k = st[-1][1]
                st.pop()

                # 前面一定有一段 1
                remove_last_bit(st)
                cnt -= 1

                # 若前面还有更高位，则这个借位后的 0 需要保留
                if st:
                    add_seg(st, 0, 1)

                # 后面 k 个 0 变成 k 个 1
                add_seg(st, 1, k)
                cnt += k

        elif ch == '*':
            # 乘 2，相当于末尾补 0；0 * 2 仍是 0
            if st:
                add_seg(st, 0, 1)

        else:  # ch == '/'
            # 除 2，相当于删最低位；0 / 2 仍是 0
            if st:
                if st[-1][0] == 1:
                    cnt -= 1
                remove_last_bit(st)

        ans.append(str(cnt))

    return ans


def main():
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()

    ans = solve_ops(s)
    sys.stdout.write('\n'.join(ans))


if __name__ == "__main__":
    main()

```

