import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;

public class Main {

    // 每一段的信息
    static class Node {
        int bit; // 这一段是 0 还是 1
        int len; // 这一段长度

        Node(int bit, int len) {
            this.bit = bit;
            this.len = len;
        }
    }

    // 向末尾加入一段，若和栈顶相同则合并
    static void addSeg(ArrayList<Node> st, int bit, int len) {
        if (len <= 0) return;

        if (!st.isEmpty() && st.get(st.size() - 1).bit == bit) {
            st.get(st.size() - 1).len += len;
        } else {
            st.add(new Node(bit, len));
        }
    }

    // 删除末尾一位
    static void removeLastBit(ArrayList<Node> st) {
        if (st.isEmpty()) return;

        Node last = st.get(st.size() - 1);
        last.len--;
        if (last.len == 0) {
            st.remove(st.size() - 1);
        }
    }

    // 处理操作串
    static StringBuilder solveOps(String s) {
        ArrayList<Node> st = new ArrayList<>(); // 二进制连续段
        int cnt = 0;                            // 当前二进制中 1 的个数
        StringBuilder ans = new StringBuilder();

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            if (ch == '+') {
                if (st.isEmpty()) {
                    // 0 + 1 = 1
                    addSeg(st, 1, 1);
                    cnt++;
                } else if (st.get(st.size() - 1).bit == 0) {
                    // 最低位是 0，直接改成 1
                    removeLastBit(st);
                    addSeg(st, 1, 1);
                    cnt++;
                } else {
                    // 末尾若干个 1 进位
                    int k = st.get(st.size() - 1).len;
                    st.remove(st.size() - 1);
                    cnt -= k;

                    if (st.isEmpty()) {
                        // 原来全是 1，例如 111 + 1 = 1000
                        addSeg(st, 1, 1);
                        cnt++;
                        addSeg(st, 0, k);
                    } else {
                        // 前面一定是 0，把那个 0 变成 1，再补 k 个 0
                        removeLastBit(st);
                        addSeg(st, 1, 1);
                        cnt++;
                        addSeg(st, 0, k);
                    }
                }
            } else if (ch == '-') {
                if (st.isEmpty()) {
                    // 0 不能再减
                } else if (st.get(st.size() - 1).bit == 1) {
                    // 最低位是 1，直接减掉这一位
                    removeLastBit(st);
                    cnt--;

                    // 若结果还大于 0，则最低位补成 0
                    if (!st.isEmpty()) {
                        addSeg(st, 0, 1);
                    }
                } else {
                    // 末尾若干个 0，需要借位
                    int k = st.get(st.size() - 1).len;
                    st.remove(st.size() - 1);

                    // 前面一定有一段 1
                    removeLastBit(st);
                    cnt--;

                    // 若前面还有更高位，则这个借位后的 0 需要保留
                    if (!st.isEmpty()) {
                        addSeg(st, 0, 1);
                    }

                    // 后面 k 个 0 变成 k 个 1
                    addSeg(st, 1, k);
                    cnt += k;
                }
            } else if (ch == '*') {
                // 乘 2，相当于末尾补 0；0 * 2 仍是 0
                if (!st.isEmpty()) {
                    addSeg(st, 0, 1);
                }
            } else { // ch == '/'
                // 除 2，相当于删最低位；0 / 2 仍是 0
                if (!st.isEmpty()) {
                    if (st.get(st.size() - 1).bit == 1) {
                        cnt--;
                    }
                    removeLastBit(st);
                }
            }

            ans.append(cnt).append('\n');
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String s = br.readLine().trim();

        System.out.print(solveOps(s).toString());
    }
}

