import sys

def add_seg(st, bit, length):
    """向栈末尾添加一段，若与栈顶相同则合并"""
    if length <= 0:
        return
    if st and st[-1][0] == bit:
        st[-1][1] += length
    else:
        st.append([bit, length])

def remove_last_bit(st):
    """删除二进制末尾一位"""
    if not st:
        return
    st[-1][1] -= 1
    if st[-1][1] == 0:
        st.pop()

def solve_ops(s):
    st = []       # 二进制连续段，每段为 [bit, len]
    cnt = 0       # 当前二进制中 1 的个数
    ans = []

    for ch in s:
        if ch == '+':
            if not st:               # E = 0
                add_seg(st, 1, 1)
                cnt += 1
            elif st[-1][0] == 0:     # 最低位是 0
                remove_last_bit(st)
                add_seg(st, 1, 1)
                cnt += 1
            else:                    # 最低位是 1，进位
                k = st[-1][1]
                st.pop()
                cnt -= k
                if not st:           # 原数全是 1
                    add_seg(st, 1, 1)
                    cnt += 1
                    add_seg(st, 0, k)
                else:
                    remove_last_bit(st)   # 前面的 0 变 1
                    add_seg(st, 1, 1)
                    cnt += 1
                    add_seg(st, 0, k)
        elif ch == '-':
            if not st:               # E = 0，忽略
                pass
            elif st[-1][0] == 1:     # 最低位是 1
                remove_last_bit(st)
                cnt -= 1
                if st:               # 若结果大于 0，补 0
                    add_seg(st, 0, 1)
            else:                    # 最低位是 0，借位
                k = st[-1][1]
                st.pop()
                remove_last_bit(st)  # 弹出一个 1
                cnt -= 1
                if st:
                    add_seg(st, 0, 1)
                add_seg(st, 1, k)
                cnt += k
        elif ch == '*':
            if st:                   # 乘以 2，末尾补 0
                add_seg(st, 0, 1)
        else:  # ch == '/'
            if st:                   # 除以 2，删除最低位
                if st[-1][0] == 1:
                    cnt -= 1
                remove_last_bit(st)

        ans.append(str(cnt))

    return ans

def main():
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()
    ans = solve_ops(s)
    sys.stdout.write('\n'.join(ans))

if __name__ == "__main__":
    main()
