        }
    }

    // 向末尾加入一段，若和栈顶相同则合并
    static void addSeg(ArrayList<Node> st, int bit, int len) {
        if (len <= 0) return;
        if (!st.isEmpty() && st.get(st.size() - 1).bit == bit) {
            st.get(st.size() - 1).len += len;
        } else {
            st.add(new Node(bit, len));
        }
    }

    // 删除末尾一位
    static void removeLastBit(ArrayList<Node> st) {
        if (st.isEmpty()) return;
        Node last = st.get(st.size() - 1);
        last.len--;
        if (last.len == 0) {
            st.remove(st.size() - 1);
        }
    }

    static StringBuilder solveOps(String s) {
        ArrayList<Node> st = new ArrayList<>(); // 二进制连续段
        int cnt = 0;                            // 当前二进制中 1 的个数
        StringBuilder ans = new StringBuilder();

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '+') {
                if (st.isEmpty()) {
                    addSeg(st, 1, 1);
                    cnt++;
                } else if (st.get(st.size() - 1).bit == 0) {
                    removeLastBit(st);
                    addSeg(st, 1, 1);
                    cnt++;
                } else {
                    int k = st.get(st.size() - 1).len;
                    st.remove(st.size() - 1);
                    cnt -= k;
                    if (st.isEmpty()) {
                        addSeg(st, 1, 1);
                        cnt++;
                        addSeg(st, 0, k);
                    } else {
                        removeLastBit(st);
                        addSeg(st, 1, 1);
                        cnt++;
                        addSeg(st, 0, k);
                    }
                }
            } else if (ch == '-') {
                if (st.isEmpty()) {
                    // E = 0，忽略
                } else if (st.get(st.size() - 1).bit == 1) {
                    removeLastBit(st);
                    cnt--;
                    if (!st.isEmpty()) {
                        addSeg(st, 0, 1);
                    }
                } else {
                    int k = st.get(st.size() - 1).len;
                    st.remove(st.size() - 1);
                    removeLastBit(st);
                    cnt--;
                    if (!st.isEmpty()) {
                        addSeg(st, 0, 1);
                    }
                    addSeg(st, 1, k);
                    cnt += k;
                }
            } else if (ch == '*') {
                if (!st.isEmpty()) {
                    addSeg(st, 0, 1);
                }
            } else { // ch == '/'
                if (!st.isEmpty()) {
                    if (st.get(st.size() - 1).bit == 1) {
                        cnt--;
                    }
                    removeLastBit(st);
                }
            }
            ans.append(cnt).append('\n');
        }
        return ans;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String s = br.readLine().trim();
        System.out.print(solveOps(s).toString());
    }
